using System;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace DungeonContract.Editor {
 public static partial class DcV7Checks {
  private static void Supplemental(){
   ReviewChecks();
   Case("expired gust direction cannot block walking through a perpendicular door",()=>{var w=World();Change(w,s=>{s["players"][0]["Room"]=2;s["players"][0]["Position"]=Point(16.975f,1.05f);s["players"][0]["DashSource"]="gust";s["players"][0]["DodgeUntil"]=0;s["players"][0]["DodgeDirection"]=Point(1,0);s["rooms"][2]["Status"]="cleared";s["rooms"][2]["Mechanism"]=true;});Step(w,3,Vector2.down);Require((int)Own(w)["room_id"]==13,"expired dash still overrode ordinary south-door intent");Require(w.Capture()["players"][0]["DashSource"].Type==JTokenType.Null,"expired dash source survived transition");});
   Case("menu input cancellation stops pending weapon action and retains skill entities and recovery",()=>{var w=World("runesmith",true);w.Action("1","charge_begin",Input(w));w.AdvanceTime(500);var input=Input(w);input.PressActionID=(string)Own(w)["charge_episode_id"];w.Action("1","charge_release",input);var ready=(long)Own(w)["melee_ready_ms"];w.Action("1","ability_primary",Input(w));w.Action("1","ability_secondary",Input(w));w.Action("1","cancel_input",Input(w));Step(w,1);Require(!(bool)Own(w)["charging"]&&Own(w)["melee_action"].Type==JTokenType.Null,"pending weapon leaked through menu cancel");Require((long)Own(w)["melee_ready_ms"]==ready&&w.Capture()["turrets"].Any()&&w.Capture()["fields"].Any(),"menu cancel refunded recovery or removed accepted persistent skills");});
   Case("inspect contract uses authored region rather than corrected respawn anchor",()=>{var w=World();Change(w,s=>{s["players"][0]["Room"]=4;s["players"][0]["Position"]=Point(5,8.75f);});Step(w,1);Require(!w.Capture()["players"][0]["Reached"].Any(r=>(string)r=="inspect_zone"),"spawn-anchor correction silently moved the contract region");Change(w,s=>s["players"][0]["Position"]=Point(4.99f,9));Step(w,1);Require(w.Capture()["players"][0]["Reached"].Any(r=>(string)r=="inspect_zone"),"authored inspect region not counted");});
   Case("temporarily occupied recovery sites wait then repeat the full warning",()=>{var w=World();w.Definition["rooms"][1]["spawn_candidates"]=new JArray{new JArray(5,9)};Change(w,s=>s["spawn_reservations"]=new JArray(new JObject{["ID"]="occupied_recovery",["Room"]=1,["Kind"]="elite",["Position"]=Point(5,9),["Until"]=1,["Recovering"]="foe_1"}));Step(w,3);Require(!w.Terminal&&(long)w.Capture()["enemies"][0]["RecoveryPlacementUntil"]>0&&!w.Capture()["spawn_reservations"].Any(),"one occupied point aborted or silently moved the enemy");Change(w,s=>s["players"][0]["Position"]=Point(10,4));Step(w,8);var r=w.Capture()["spawn_reservations"].FirstOrDefault();Require(r!=null&&(long)r["Until"]-w.GameTime>=700,"reselection skipped the complete800ms warning");Require(Math.Abs((float)w.Capture()["enemies"][0]["Position"]["x"]-20)<.01f,"recovery teleported before warning finished");});
   Case("blade and hammer thickness cannot extend reach beyond the visible tip",()=>{foreach(var range in new[]{1.333f,3.25f}){var width=range<2?.08f:.3f;var inner=range<2?.4f+(range-.4f)*.35f:range-.6f;var inside=new Vector2(range-.01f,0);var beyond=new Vector2(range+.01f,0);Require(DcV7Geometry.VisibleWeaponCircle(Vector2.zero,Vector2.zero,0,0,inner,range,width,inside,inside,.001f).HasValue,"visible tip has no contact");Require(!DcV7Geometry.VisibleWeaponCircle(Vector2.zero,Vector2.zero,0,0,inner,range,width,beyond,beyond,.001f).HasValue,"hidden extra capsule reach");}});
   Case("autoplay holds four-second interaction without self-interrupting gust",()=>{foreach(var guard in new[]{false,true}){var w=World();Change(w,s=>{s["players"][0]["Room"]=2;s["players"][0]["Position"]=Point(22,10);s["rooms"][2]["Status"]="active";s["rooms"][2]["Wave"]=1;s["enemies"][0]["Room"]=2;});for(var tick=1;tick<=145;tick++){var input=Input(w);input.Interact=true;var actions=tick%119==0?new[]{"ability_primary"}:Array.Empty<string>();if(guard)DcV7Pilot.InteractionGuard(input,ref actions);foreach(var action in actions)w.Action("1",action,input);w.Input("1",input);w.Tick((tick*1000+29)/30);w.DrainV6Lifecycle();}Require((bool)w.Snapshot()["rooms"][2]["mechanism_complete"]==guard,"interaction test did not distinguish the valid rule from bot self-interruption");}});
   Case("dynamic actor translation updates derived visible body center",()=>{var w=World();var baseline=w.Snapshot();baseline["protocol_version"]=7;baseline["state_revision"]=1;baseline["interest_revision"]=1;baseline["lifecycle_watermark"]=0;DcS1Replica.PackV6Baseline(baseline,true);var replica=new DcS1Replica();replica.Baseline(baseline,"1",1);Step(w,1,Vector2.down);var next=w.Snapshot();next["protocol_version"]=7;foreach(var packet in DcS1Replica.EncodeV6(next,1,1,1,"1"))replica.Dynamic(packet,1,1);var p=replica.Snapshot["players"][0];Require(Math.Abs((float)p["body_center_y"]-(float)Own(w)["body_center_y"])<.001f,"body center metadata stayed at old reliable foot position");});
   Case("network probe aligns visible center before walking across east doors",()=>{var w=World();Change(w,s=>{s["players"][0]["Room"]=0;s["players"][0]["Position"]=Point(3,6);});for(var tick=0;tick<150&&(int)Own(w)["room_id"]==0;tick++){var p=Own(w);Step(w,1,DcV7Pilot.EastDoorMove((JObject)w.Definition["rooms"][(int)p["room_id"]],p));}Require((int)Own(w)["room_id"]!=0,"raw foot-aligned input never crossed door with taller body");});
   Case("direction changes preserve previous visible center in continuous sweeps",()=>{var w=World(melee:true);Step(w,1,aim:32768);var left=Own(w);var old=new Vector2((float)left["body_center_x"],(float)left["body_center_y"]);Step(w,1,Vector2.right,aim:0);var p=w.Capture()["players"][0];Require(Vector2.Distance(old,new Vector2((float)p["TickStartCenter"]["x"],(float)p["TickStartCenter"]["y"]))<.0001f,"sweep reconstructed old center using the new body facing");});
   Case("single and twin turrets inherit rune lifetime radius and600ms cadence",()=>{foreach(var twin in new[]{false,true}){var w=World("runesmith");Change(w,s=>{s["players"][0]["Upgrades"]=twin?new JArray("runesmith_twin"):new JArray();s["enemies"][0]["Position"]=Point(12,9);});Require(w.Action("1","ability_primary",Input(w)),"turret deploy");Step(w,1);var state=w.Capture();Require(state["turrets"].Count()==(twin?2:1),"turret count");Require(state["projectiles"].Count()==(twin?2:1),"first turret volley");foreach(var p in state["projectiles"])Require((bool)p["RuneBolt"]&&Math.Abs((float)p["CollisionRadius"]-.3f)<.0001f&&(long)p["ExpiresGameMS"]-(long)p["BornGameMS"]==6000&&(int)p["Damage"]==(twin?9:14),"turret inheritance");Step(w,18);Require(w.Capture()["projectiles"].Count()>=(twin?4:2),"600ms cadence was changed to900ms");}});
   Case("one chain root survives repeated rune contact without repeated chain procs",()=>{var w=World("runesmith");Change(w,s=>{s["enemies"][0]["Position"]=Point(10,9);var other=(JObject)s["enemies"][0].DeepClone();other["ID"]="foe_2";other["Position"]=Point(12,9);((JArray)s["enemies"]).Add(other);var p=Bullet(x:6);p["ChainEnabled"]=true;s["projectiles"]=new JArray(p);});Step(w,175);Require(w.Capture()["v5_chain_roots"].Count()==1,"repeat contact created a second chain root");Require((int)w.Capture()["enemies"][0]["Health"]<=9968,"fixture did not produce actual reentry damage");});
   Case("contact budget parks legal flights and persistent exhaustion enters wait",()=>{var w=World("runesmith");((JArray)w.Definition["rooms"][1]["obstacles"]).Add(new JArray(6,1,1,16));((JArray)w.Definition["rooms"][1]["obstacles"]).Add(new JArray(8,1,1,16));Change(w,s=>s["projectiles"]=new JArray(Bullet(x:7.5f,speed:100000)));Step(w,1);var p=w.Capture()["projectiles"][0];Require(w.V7ContactBudgetParks==1&&!w.Terminal&&(long)p["ExpiresGameMS"]==6000,"budget silently deleted or extended flight");Require((float)p["Position"]["x"]>=7.299f&&(float)p["Position"]["x"]<=7.701f,"park crossed wall");Step(w,29);Require(!w.Terminal&&(bool)w.Capture()["technical_waiting"]&&w.Capture()["projectiles"].Count()==0,"persistent exhaustion did not enter bounded technical wait");});
  }
 }
